#include <stdio.h>
#include <setjmp.h>

jmp_buf env;

void nested_function() {
  if (setjmp(env) == 0) {
    printf("Nested function called\n");
    // Simulate an error condition
    longjmp(env, 1);
  }
  else {
    printf("Returning from longjmp\n");
  }
}

int main() {
  if (setjmp(env) == 0) {
    printf("Main function called\n");
    nested_function();
    printf("Main function continues\n");
  } else {
    printf("Returning to main from longjmp\n");
  }
  return 0;
}
